const lerp = (a, b, t) => a + (b - a) * t;
const curves = [
  ['선형', (t) => t],
  ['ease-out', (t) => 1 - (1 - t) ** 3],
  ['튕김', (t) => 1 + 2.7 * (t - 1) ** 3 + 1.7 * (t - 1) ** 2],
];
function frame(now) {
  const T = (now % 2000) / 2000;
  ctx.clearRect(0, 0, W(), H());
  curves.forEach(([name, f], i) => {
    const y = 40 + i * 46;
    ctx.fillStyle = '#333'; ctx.fillRect(20, y, W() - 40, 4);
    ctx.fillStyle = '#eee'; ctx.font = '12px system-ui'; ctx.fillText(name, 20, y - 10);
    const x = lerp(24, W() - 24, Math.min(1, Math.max(0, f(T))));
    ctx.beginPath(); ctx.arc(x, y + 2, 9, 0, Math.PI * 2);
    ctx.fillStyle = '#60a5fa'; ctx.fill();
  });
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

